# v336: base-building balance before Astrophysics Lv.2 (owner's pattern: Metal 8, Crystal 6, Gas 4, Solar in between, then storage, then radar)
p = 'docs/index.html'; t = open(p, encoding='utf-8').read()
def rep(a, b, n=1):
    global t; assert t.count(a) == n, (a[:80], t.count(a)); t = t.replace(a, b)
STEPS = '''  /* v336: a balanced homeworld before the second one. The owner's pattern: power first, Metal 8, Crystal 6, Gas 4 with the Solar Array
     raised in between whenever the extractors outgrow it, then storage so full silos don't stop the mines, then a Radar Station.
     Every level here takes seconds and the Academy pays for it */
  { lv: 5, id: "econ-solar5", t: "Upgrade the Solar Array to Lv.5", say: "Before we claim a second world, our first one has to run properly. Our extractors are starved for power: Structures shows a red Power shortage card. Rule one of a strong economy: power first. Take the Solar Array to Lv.5.", ok: () => lvlOf("solar") >= 5, go: { v: "build", s: "res" }, path: bPath("solar", "res"), fund: () => bFund("solar", 5), rw: { m: 1500, c: 1000, g: 300 } },
  { lv: 5, id: "econ-metal6", t: "Upgrade the Metal Extractor to Lv.6", say: "Metal is what we spend the most: every hull and every building. So metal is always our highest extractor. Take it to Lv.6.", ok: () => lvlOf("metalMine") >= 6, go: { v: "build", s: "res" }, path: bPath("metalMine", "res"), fund: () => bFund("metalMine", 6), rw: { m: 1500, c: 1000, g: 300 } },
  { lv: 5, id: "econ-solar7", t: "Upgrade the Solar Array to Lv.7", say: "Every extractor level draws more power. Whenever the Power shortage card turns red, the Solar Array comes next. Take it to Lv.7.", ok: () => lvlOf("solar") >= 7, go: { v: "build", s: "res" }, path: bPath("solar", "res"), fund: () => bFund("solar", 7), rw: { m: 2000, c: 1200, g: 400 } },
  { lv: 5, id: "econ-crystal6", t: "Upgrade the Crystal Refinery to Lv.6", say: "Crystal comes second: research and better hulls run on it. Keep it two levels behind metal. Take the Crystal Refinery to Lv.6.", ok: () => lvlOf("crystalMine") >= 6, go: { v: "build", s: "res" }, path: bPath("crystalMine", "res"), fund: () => bFund("crystalMine", 6), rw: { m: 2000, c: 1200, g: 400, shards: 1 } },
  { lv: 5, id: "econ-metal8", t: "Upgrade the Metal Extractor to Lv.8", say: "Back to metal. Metal Lv.8, Crystal Lv.6, Gas Lv.4: that is the balance strong empires run on. Take the Metal Extractor to Lv.8.", ok: () => lvlOf("metalMine") >= 8, go: { v: "build", s: "res" }, path: bPath("metalMine", "res"), fund: () => bFund("metalMine", 8), rw: { m: 2500, c: 1500, g: 500 } },
  { lv: 5, id: "econ-solar9", t: "Upgrade the Solar Array to Lv.9", say: "Power again, before the gas. The Gas Synthesizer draws the most power of all, so the Solar Array goes to Lv.9 first.", ok: () => lvlOf("solar") >= 9, go: { v: "build", s: "res" }, path: bPath("solar", "res"), fund: () => bFund("solar", 9), rw: { m: 2500, c: 1500, g: 500 } },
  { lv: 5, id: "econ-gas4", t: "Upgrade the Gas Synthesizer to Lv.4", say: "Gas fuels fleets and research, but we need less of it, so it stays lowest. Take it to Lv.4 and our pattern is complete: Metal 8, Crystal 6, Gas 4, with the Solar Array keeping up.", ok: () => lvlOf("gasSynth") >= 4, go: { v: "build", s: "res" }, path: bPath("gasSynth", "res"), fund: () => bFund("gasSynth", 4), rw: { m: 3000, c: 2000, g: 1000, shards: 1 } },
  { lv: 5, id: "econ-store", t: "Upgrade your storage to Lv.2", say: "Our extractors now dig faster than we can store. When a silo is full, its extractor stops. Take the Metal Silo, the Crystal Vault and the Gas Tank to Lv.2 so nothing goes to waste.", ok: () => ECON_STORE.every(k => lvlOf(k) >= 2), go: { v: "build", s: "res" }, path: () => bPath(ECON_STORE.find(k => lvlOf(k) < 2) || "metalStore", "res")(), fund: () => ECON_STORE.reduce((c, k) => addC(c, bFund(k, 2)), {}), rw: { m: 3000, c: 2000, g: 1000 } },
  { lv: 5, id: "econ-radar", t: "Build a Radar Station", say: "A rich world draws raiders. A Radar Station spots enemy fleets on their way to us, earlier with every level. Build it under Facility. From now on, every world we hold gets the same order: power, metal, crystal, gas, storage, radar.", ok: () => lvlOf("radar") >= 1, go: { v: "build", s: "fac" }, path: bPath("radar", "fac"), fund: () => bFund("radar", 1), rw: { m: 3000, c: 3000, g: 1000, shards: 2 } },
'''
rep('  { lv: 5, t: "Research Astrophysics Lv.2"', STEPS + '  { lv: 5, t: "Research Astrophysics Lv.2"')
rep('const tutAt = id =>', 'const ECON_STORE = ["metalStore", "crystalStore", "gasTank"]; // v336\nconst tutAt = id =>')
rep('''  if (!G.tutFound) { G.tutFound = 1;''', '''  if (!S.tutEcon) { S.tutEcon = 1; if (S.tut.k === "research-astrophysics-lv-2" && (S.r.astro || 0) < 2) S.tut.k = "econ-solar5"; else if (!S.tut.k && S.tut.i >= 29) S.tut.i = Math.min(TUT.length, S.tut.i + 9); dirty(); } /* v336: nine economy steps before Astrophysics Lv.2; anyone waiting on Lv.2 gets them first, anyone past it keeps their place */
  if (!G.tutFound) { G.tutFound = 1;''')
open(p, 'w', encoding='utf-8').write(t); print('ok')
